#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_print_number_positive_digits_to_print(void) {
    uint8_t N = 5;
    uint8_t number[] = {0, 0, 3, 2, 1};
    int8_t num_digits_to_print = 3;
    stdout_capture_t *cap = capture_stdout_start();

    int result = print_number(number, N, num_digits_to_print);

    char *output = capture_stdout_stop(cap);
    TEST_ASSERT_EQUAL_INT(0, result);
    TEST_ASSERT_EQUAL_STRING("123
", output);
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_print_number_positive_digits_to_print);
    return UNITY_END();
}

